-- v55.83-SW — correspondence rules, on a local Postgres (never Supabase). Run after the SV and SW scripts.
create or replace function public.try(q text) returns text language plpgsql as $$ begin execute q; return 'ALLOWED'; exception when others then return 'REFUSED: ' || left(sqlerrm, 105); end $$;
insert into public.sourcing_requests(id, company, direction, title, product) values ('11111111-0000-0000-0000-0000000000a1','KTC Egypt','buy','Loaders','used CAT 950') on conflict do nothing;
insert into public.suppliers(id, legal_name, name_key) values ('22222222-0000-0000-0000-0000000000a1','Acme','acme sw'), ('22222222-0000-0000-0000-0000000000a2','Beta','beta sw') on conflict do nothing;
select 'W0 Stage-1 drafts carried over: ' || count(*) from public.commercial_messages where subject = 'carried over';
select 'W1 an outgoing message created as already approved: ' || public.try($q$insert into public.commercial_messages(request_id,supplier_id,direction,to_address,subject,body,status) values ('11111111-0000-0000-0000-0000000000a1','22222222-0000-0000-0000-0000000000a1','out','a@b.co','s','b','approved')$q$);
insert into public.commercial_messages(id, request_id, supplier_id, direction, to_address, subject, body, status) values ('33333333-0000-0000-0000-0000000000a1','11111111-0000-0000-0000-0000000000a1','22222222-0000-0000-0000-0000000000a1','out','sales@acme.example','Inquiry — SR-0001','Dear Sir,','draft');
select 'W2 the hash is computed by the database: ' || (content_hash = md5('sales@acme.example|Inquiry — SR-0001|Dear Sir,'))::text from public.commercial_messages where id='33333333-0000-0000-0000-0000000000a1';
select 'W3 a second live draft for the same supplier: ' || public.try($q$insert into public.commercial_messages(request_id,supplier_id,direction,to_address,subject,body,status) values ('11111111-0000-0000-0000-0000000000a1','22222222-0000-0000-0000-0000000000a1','out','x@y.co','s','b','draft')$q$);
select 'W4 approved without naming the version: ' || public.try($q$update public.commercial_messages set status='approved', approved_by='00000000-0000-0000-0000-000000000009' where id='33333333-0000-0000-0000-0000000000a1'$q$);
select 'W5 sent straight from draft: ' || public.try($q$update public.commercial_messages set status='sending' where id='33333333-0000-0000-0000-0000000000a1'$q$);
update public.commercial_messages set status='pending_approval', submitted_at=now() where id='33333333-0000-0000-0000-0000000000a1';
update public.commercial_messages set status='approved', approved_by='00000000-0000-0000-0000-000000000009', approved_at=now(), approved_hash=content_hash where id='33333333-0000-0000-0000-0000000000a1';
select 'W6 approved for this exact version: ' || status from public.commercial_messages where id='33333333-0000-0000-0000-0000000000a1';
update public.commercial_messages set body = 'Dear Sir, we would pay up to $50,000' where id='33333333-0000-0000-0000-0000000000a1';
select 'W7 changed after approval → ' || status || ', approval cleared: ' || (approved_hash is null)::text from public.commercial_messages where id='33333333-0000-0000-0000-0000000000a1';
update public.commercial_messages set body = 'Dear Sir,' where id='33333333-0000-0000-0000-0000000000a1';
update public.commercial_messages set status='approved', approved_by='00000000-0000-0000-0000-000000000009', approved_at=now(), approved_hash=content_hash where id='33333333-0000-0000-0000-0000000000a1';
select 'W8 sending with a stale approval: ' || public.try($q$update public.commercial_messages set status='sending', approved_hash='abc' where id='33333333-0000-0000-0000-0000000000a1'$q$);
with x as (update public.commercial_messages set status='sending', attempts=attempts+1 where id='33333333-0000-0000-0000-0000000000a1' and status='approved' returning status) select 'W9 claim for sending (only if still approved): ' || coalesce((select status from x), 'nothing');
with x as (update public.commercial_messages set status='sending' where id='33333333-0000-0000-0000-0000000000a1' and status='approved' returning status) select 'W10 claimed a second time (two senders at once): ' || coalesce((select status from x), 'nothing — already being sent');
select 'W11 marked sent without a Message-ID: ' || public.try($q$update public.commercial_messages set status='sent' where id='33333333-0000-0000-0000-0000000000a1'$q$);
update public.commercial_messages set status='sent', message_id='<sourcing-1@ktcus.com>', sent_at=now() where id='33333333-0000-0000-0000-0000000000a1';
select 'W12 a sent message rewritten: ' || public.try($q$update public.commercial_messages set body='changed' where id='33333333-0000-0000-0000-0000000000a1'$q$);
select 'W13 a sent message moved back to draft: ' || public.try($q$update public.commercial_messages set status='draft' where id='33333333-0000-0000-0000-0000000000a1'$q$);
select 'W14 a sent message deleted: ' || public.try($q$delete from public.commercial_messages where id='33333333-0000-0000-0000-0000000000a1'$q$);
select 'W15 sent → bounced: ' || public.try($q$update public.commercial_messages set status='bounced', last_error='550 no such user' where id='33333333-0000-0000-0000-0000000000a1'$q$);
select 'W16 the same Message-ID imported twice: ' || public.try($q$insert into public.commercial_messages(request_id,supplier_id,direction,kind,from_address,subject,body,status,message_id) values ('11111111-0000-0000-0000-0000000000a1','22222222-0000-0000-0000-0000000000a1','in','inbound','x@y.co','Re','r','received','<sourcing-1@ktcus.com>')$q$);
select 'W17 an incoming reply: ' || public.try($q$insert into public.commercial_messages(request_id,supplier_id,direction,kind,from_address,subject,body,status,message_id,in_reply_to) values ('11111111-0000-0000-0000-0000000000a1','22222222-0000-0000-0000-0000000000a1','in','inbound','sales@acme.example','Re: Inquiry','Price 41,500 FOB','received','<reply-77@acme.example>','<sourcing-1@ktcus.com>')$q$);
select 'W18 an incoming reply rewritten: ' || public.try($q$update public.commercial_messages set body='Price 31,500' where message_id='<reply-77@acme.example>'$q$);
select 'W19 an outgoing draft with no valid address sent for approval: ' || public.try($q$insert into public.commercial_messages(request_id,supplier_id,direction,subject,body,status) values ('11111111-0000-0000-0000-0000000000a1','22222222-0000-0000-0000-0000000000a2','out','s','b','draft'); update public.commercial_messages set status='pending_approval' where supplier_id='22222222-0000-0000-0000-0000000000a2' and status='draft'$q$);
select 'W20 RLS: ' || count(*) filter (where relrowsecurity) || ' of ' || count(*) || '; web roles can read: ' || coalesce((select string_agg(distinct grantee, ',') from information_schema.role_table_grants where grantee in ('anon','authenticated') and table_name in ('commercial_messages','commercial_mail_state')), 'none') from pg_class where relname in ('commercial_messages','commercial_mail_state');
drop function public.try(text);
